+        toxicity: 0.9
+      }
+    });
+
+    expect(report.passed).toBe(true);
+    expect(report.thresholds).toEqual([
+      { metric: 'exact_match', min: 1.0, score: 1.0, passed: true },
+      { metric: 'toxicity', min: 0.9, score: 1, passed: true }
+    ]);
+  });
+
+  it('fails threshold when score is below minimum', () => {
+    const evaluations = runEvaluations({
+      outputs: ['Hello'],
