447	function checkForUpdates() {
448	  const currentVersion = pkg.version ?? '0.0.0';
449	  try {
450	    const remote = execSync('npm view frai version', { encoding: 'utf8' }).trim();
451	    if (!remote) {
452	      log.warn('Unable to determine latest version from npm.');
453	      return;
454	    }
455	    if (remote === currentVersion) {
456	      log.success('You are running the latest FRAI CLI release.', { version: currentVersion });
457	    } else {
458	      log.info('A newer FRAI CLI release is available.', {
459	        current: currentVersion,
460	        latest: remote
461	      });
462	      console.log(`Update with: npm install -g frai@${remote}`);
463	    }
464	  } catch (error) {
465	    log.warn('Failed to check for updates.', {
466	      error: error instanceof Error ? error.message : String(error)
467	    });
468	  }
469	}
