477	function runEvalCommand(options: EvalOptions) {
478	  assertFileExists(options.outputs);
479	
480	  let thresholds: Record<string, number> | undefined;
481	  if (options.threshold && options.threshold.length > 0) {
482	    thresholds = {};
483	
484	    for (const thresholdStr of options.threshold) {
485	      const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
486	      if (!match) {
487	        log.error(`Malformed threshold: ${thresholdStr}. Expected format: <metric>=<number>`);
488	        process.exit(2);
489	      }
490	
491	      const [, metricId, valueStr] = match;
492	      const value = Number.parseFloat(valueStr);
493	
494	      if (!Number.isFinite(value) || value < 0 || value > 1) {
495	        log.error(`Invalid threshold value: ${valueStr}. Must be a number between 0 and 1.`);
496	        process.exit(2);
497	      }
498	
499	      thresholds[metricId] = value;
500	    }
501	  }
502	
503	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
504	    outputsPath: options.outputs,
505	    referencesPath: options.references
506	  });
507	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
508	    outputs: dataset.outputs,
509	    references: dataset.references
510	  });
511	
512	  if (thresholds) {
513	    const evaluatedMetricIds = new Set((evaluations as Array<{ id: string }>).map((m) => m.id));
514	    for (const metricId of Object.keys(thresholds)) {
515	      if (!evaluatedMetricIds.has(metricId)) {
516	        const validMetrics = Array.from(evaluatedMetricIds).join(', ');
517	        log.error(`Unknown metric: ${metricId}. Valid metrics: ${validMetrics}`);
518	        process.exit(2);
519	      }
520	    }
521	  }
522	
523	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
524	    evaluations,
525	    outputsPath: dataset.outputsPath,
526	    referencesPath: dataset.referencesPath,
527	    thresholds
528	  });
529	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
530	    report,
531	    format: options.format ?? 'json',
532	    reportPath: options.report
533	  });
534	  log.success('Evaluation report generated.', { path: resolvedPath });
535	
536	  if (thresholds && report.passed === false) {
537	    process.exit(1);
538	  }
539	}
