477	function runEvalCommand(options: EvalOptions) {
478	  assertFileExists(options.outputs);
479	
480	  let thresholds: Record<string, number> | undefined;
481	  if (options.threshold && options.threshold.length > 0) {
482	    thresholds = {};
483	
484	    for (const thresholdStr of options.threshold) {
485	      const equalsIndex = thresholdStr.indexOf('=');
486	      if (equalsIndex === -1) {
487	        log.error(`Malformed threshold: ${thresholdStr}. Expected format: <metric>=<number>`);
488	        process.exit(2);
489	      }
490	
491	      const metricId = thresholdStr.substring(0, equalsIndex);
492	      const valueStr = thresholdStr.substring(equalsIndex + 1);
493	
494	      if (!metricId) {
495	        log.error(`Malformed threshold: ${thresholdStr}. Expected format: <metric>=<number>`);
496	        process.exit(2);
497	      }
498	
499	      const value = Number(valueStr);
500	
501	      if (!Number.isFinite(value) || value < 0 || value > 1) {
502	        log.error(`Invalid threshold value: ${valueStr}. Must be a number between 0 and 1.`);
503	        process.exit(2);
504	      }
505	
506	      if (thresholds[metricId] !== undefined) {
507	        log.error(`Duplicate threshold: ${metricId}. Each metric can have at most one threshold.`);
508	        process.exit(2);
509	      }
510	
511	      thresholds[metricId] = value;
512	    }
513	  }
514	
515	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
516	    outputsPath: options.outputs,
